document.querySelector('.menu-toggle').addEventListener('click',()=>{const navLinks=document.getElementById('nav-links');navLinks.classList.toggle('show')});function renderCart(){const cartItems=document.getElementById('cart-items');const cartTotal=document.getElementById('cart-total');cartItems.innerHTML='';const cart=JSON.parse(localStorage.getItem('cart'))||[];let total=0;if(cart.length===0){const li=document.createElement('li');li.textContent='Votre panier est vide.';cartItems.appendChild(li)}else{cart.forEach((item,index)=>{const li=document.createElement('li');const span=document.createElement('span');span.textContent=`${item.name} - $${item.price}`;const removeBtn=document.createElement('button');removeBtn.type='button';removeBtn.textContent='✕';removeBtn.setAttribute('aria-label',`Retirer ${item.name} du panier`);removeBtn.addEventListener('click',()=>{cart.splice(index,1);localStorage.setItem('cart',JSON.stringify(cart));renderCart()});li.appendChild(span);li.appendChild(removeBtn);cartItems.appendChild(li);total+=parseFloat(item.price)})}
cartTotal.textContent=total.toFixed(2);updateCartBadge(cart.length)}
function updateCartBadge(count){const cartButton=document.getElementById('cart');let badge=document.getElementById('cart-badge');if(!badge){badge=document.createElement('span');badge.id='cart-badge';cartButton.appendChild(badge)}
badge.textContent=count;badge.style.display=count>0?'inline-block':'none'}
document.querySelectorAll('.add-to-cart').forEach(button=>{button.addEventListener('click',()=>{const productName=button.getAttribute('data-name');const productPrice=button.getAttribute('data-price');let cart=JSON.parse(localStorage.getItem('cart'))||[];cart.push({name:productName,price:productPrice});localStorage.setItem('cart',JSON.stringify(cart));renderCart();alert(`${productName} a été ajouté au panier!`)})});document.getElementById('cart').addEventListener('click',()=>{const cartContent=document.getElementById('cart-content');renderCart();cartContent.style.display='block'})